#!/usr/bin/env python3
"""
Read {{p:vendor}}-firmware-audit.csv and print devices grouped by firmware version.
Adds error handling for missing file.
"""
import csv
import os
import sys

CSV_FILE = "{{p:vendor}}-firmware-audit.csv"

def main():
    if not os.path.isfile(CSV_FILE):
        sys.stderr.write(f"Error: File '{CSV_FILE}' not found. Please ensure the CSV file is present.\n")
        sys.exit(1)

    groups = {}
    try:
        with open(CSV_FILE, newline="") as f:
            reader = csv.DictReader(f)
            for row in reader:
                fw = row.get("Firmware Version", "<unknown>")
                hostname = row.get("Hostname (sysName)", row.get("sysName", "<no hostname>"))
                groups.setdefault(fw, []).append(hostname)
    except Exception as e:
        sys.stderr.write(f"Error reading '{CSV_FILE}': {e}\n")
        sys.exit(1)

    for fw, hosts in sorted(groups.items()):
        print(f"Firmware Version: {fw}")
        for h in hosts:
            print(f"  - {h}")
        print()

if __name__ == "__main__":
    main()
